    ;(design_studio_ref01_data_up0 as any)[design_studio_ref01_markdef_up0.name] = design_studio_ref01_markdef_up0.value

    const design_studio_ref01_resdata_up0 = (await design_studio_ref01_ent.update(design_studio_ref01_data_up0)).data()
